include("auth_owner.php");include("db.php");include("functions.php");$stmt=mysqli_prepare($conn,"SELECT rr.*,i.item_name,p.full_name FROM rental_requests rr JOIN items i ON i.item_id=rr.item_id LEFT JOIN user_profiles p ON p.user_id=rr.borrower_id WHERE i.owner_id=? AND rr.status IN ('completed','rejected','cancelled') ORDER BY rr.request_id DESC");mysqli_stmt_bind_param($stmt,"i",$owner_id);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$rows=[];while($x=mysqli_fetch_assoc($res))$rows[]=$x;mysqli_stmt_close($stmt);$current='history';
