<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Owner History | BorrowBee</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><div class="app-layout"><?php include("owner_sidebar.php"); ?><main class="main-content"><header class="topbar"><div><h1>History</h1><p class="topbar-sub">Closed rental activity for your items.</p></div></header><section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Request</th><th>Borrower</th><th>Item</th><th>Dates</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5">No history yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td>#<?php echo (int)$r['request_id']; ?></td><td><?php echo e($r['full_name']?:'Borrower'); ?></td><td><?php echo e($r['item_name']); ?></td><td><?php echo e($r['start_date']); ?> → <?php echo e($r['end_date']); ?></td><td><span class="status-pill status-<?php echo e($r['status']); ?>"><?php echo e(ucfirst($r['status'])); ?></span></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>
